LOCK TABLE public.reading_materials,public.uploaded_pdfs,public.user_vocabulary,public.vocabulary_contexts,public.user_known_words,public.review_events,public.vocabulary_exclusions,public.fsrs_cards,public.fsrs_operations,public.fsrs_new_receipts,fsrs_private.settings,fsrs_private.event_permits IN SHARE ROW EXCLUSIVE MODE;
