CREATE FUNCTION pg_temp.fsrs019_new_table_catalog() RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $table_catalog$-- Portable values for the two exact new definitions; no live OIDs enter the approved baseline.
WITH new_tables AS (
 SELECT c.* ,n.nspname FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 WHERE (n.nspname,c.relname) IN (('fsrs_private','manual_save_settings'),('public','fsrs_manual_save_receipts'))
)
SELECT jsonb_object_agg(t.nspname||'.'||t.relname,jsonb_build_object(
 'relation',jsonb_build_object('kind',t.relkind,'persistence',t.relpersistence,'rls',t.relrowsecurity,'forceRls',t.relforcerowsecurity,
  'partition',t.relispartition,'replicaIdentity',t.relreplident,'options',t.reloptions,'checks',t.relchecks,'hasRules',t.relhasrules,
  'hasSubclass',t.relhassubclass,'accessMethod',(SELECT amname FROM pg_catalog.pg_am WHERE oid=t.relam)),
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'number',a.attnum,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),
  'notNull',a.attnotnull,'hasDefault',a.atthasdef,'identity',a.attidentity,'generated',a.attgenerated,'dimensions',a.attndims,
  'dropped',a.attisdropped,'storage',a.attstorage,'compression',a.attcompression,'acl',a.attacl,
  'collation',(SELECT n.nspname||'.'||c.collname FROM pg_catalog.pg_collation c JOIN pg_catalog.pg_namespace n ON n.oid=c.collnamespace WHERE c.oid=a.attcollation),
  'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum)
  FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=t.oid AND a.attnum>0),
 'constraints',coalesce((SELECT jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'deferrable',c.condeferrable,
  'deferred',c.condeferred,'validated',c.convalidated,'local',c.conislocal,'inheritCount',c.coninhcount,'noInherit',c.connoinherit,
  'definition',pg_catalog.pg_get_constraintdef(c.oid)) ORDER BY c.conname) FROM pg_catalog.pg_constraint c WHERE c.conrelid=t.oid AND c.contype<>'n'),'[]'::jsonb),
 'indexes',coalesce((SELECT jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'persistence',c.relpersistence,'options',c.reloptions,
  'definition',pg_catalog.pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,
  'unique',i.indisunique,'primary',i.indisprimary,'exclusion',i.indisexclusion,'immediate',i.indimmediate,'clustered',i.indisclustered,
  'replicaIdentity',i.indisreplident,'keyCount',i.indnkeyatts,'attributeCount',i.indnatts,'checkXmin',i.indcheckxmin,
  'accessMethod',(SELECT amname FROM pg_catalog.pg_am WHERE oid=c.relam)) ORDER BY c.relname)
  FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=t.oid),'[]'::jsonb),
 'policies',coalesce((SELECT jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,
  'roles',(SELECT jsonb_agg(coalesce(r.rolname,'PUBLIC') ORDER BY coalesce(r.rolname,'PUBLIC')) FROM unnest(p.polroles) pr(oid) LEFT JOIN pg_catalog.pg_roles r USING(oid)),
  'using',pg_catalog.pg_get_expr(p.polqual,p.polrelid),'withCheck',pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname)
  FROM pg_catalog.pg_policy p WHERE p.polrelid=t.oid),'[]'::jsonb)
) ORDER BY t.nspname,t.relname) FROM new_tables t;
$table_catalog$;
CREATE FUNCTION pg_temp.fsrs019_catalog() RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $catalog$
 WITH RECURSIVE relevant_roles(oid) AS (
  SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role') OR oid=(SELECT nspowner FROM pg_namespace WHERE nspname='fsrs_private')
  UNION SELECT m.roleid FROM pg_auth_members m JOIN relevant_roles r ON r.oid=m.member
 ), tables AS (SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='fsrs_private' OR (n.nspname='public' AND c.relname LIKE 'fsrs\_%' ESCAPE '\')),
 objects AS (
  SELECT 'relation:'||c.oid::text k,jsonb_build_array(c.relkind,c.relowner,c.relacl,c.relrowsecurity,c.relforcerowsecurity,c.reloptions) v FROM tables c
  UNION ALL SELECT 'column:'||c.oid::text||':'||a.attnum::text,jsonb_build_array(a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.attacl,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid)) FROM tables c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped
  UNION ALL SELECT 'constraint:'||x.oid::text,to_jsonb(pg_get_constraintdef(x.oid)) FROM pg_constraint x JOIN tables c ON x.conrelid=c.oid
  UNION ALL SELECT 'policy:'||p.oid::text,jsonb_build_array(p.polcmd,p.polpermissive,p.polroles,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) FROM pg_policy p JOIN tables c ON p.polrelid=c.oid
  UNION ALL SELECT 'view:'||c.oid::text,to_jsonb(pg_get_viewdef(c.oid,true)) FROM tables c WHERE c.relkind='v'
  UNION ALL SELECT 'index:'||i.indexrelid::text,jsonb_build_array(pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready) FROM pg_index i JOIN tables c ON c.oid=i.indrelid
  UNION ALL SELECT 'function:'||p.oid::text,jsonb_build_array(pg_get_functiondef(p.oid),p.proacl,p.proowner) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='fsrs_private' OR (n.nspname='public' AND (p.proname LIKE 'fsrs\_%' ESCAPE '\' OR p.proname='learning_language_capabilities'))
  UNION ALL SELECT 'trigger:'||t.oid::text,jsonb_build_array(pg_get_triggerdef(t.oid),t.tgenabled) FROM pg_trigger t WHERE t.tgname IN ('fsrs_guard_legacy_vocabulary','fsrs_guard_legacy_event')
  UNION ALL SELECT 'schema:'||n.oid::text,jsonb_build_array(n.nspowner,n.nspacl) FROM pg_namespace n WHERE n.nspname IN ('fsrs_private','public','auth')
  UNION ALL SELECT 'role:'||r.oid::text,jsonb_build_array(r.rolsuper,r.rolbypassrls,r.rolinherit) FROM pg_roles r JOIN relevant_roles rr ON rr.oid=r.oid
  UNION ALL SELECT 'membership:'||m.member::text||':'||m.roleid::text,to_jsonb(m) FROM pg_auth_members m JOIN relevant_roles r ON r.oid=m.member
 ) SELECT jsonb_object_agg(k,v ORDER BY k) FROM objects
$catalog$;
CREATE TEMP TABLE fsrs019_preserve_0 ON COMMIT DROP AS TABLE public.reading_materials;
CREATE TEMP TABLE fsrs019_preserve_1 ON COMMIT DROP AS TABLE public.uploaded_pdfs;
CREATE TEMP TABLE fsrs019_preserve_2 ON COMMIT DROP AS TABLE public.user_vocabulary;
