CREATE TEMP TABLE fsrs019_preserve_6 ON COMMIT DROP AS TABLE public.vocabulary_exclusions;
CREATE TEMP TABLE fsrs019_preserve_7 ON COMMIT DROP AS TABLE public.fsrs_cards;
