 IF EXISTS(SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid=ANY(ARRAY['fsrs_private.manual_save_settings'::regclass,'public.fsrs_manual_save_receipts'::regclass]) AND NOT tgisinternal)
