  THEN RAISE EXCEPTION 'fsrs019_unexpected_new_table_trigger_or_rule'; END IF;
 IF pg_temp.fsrs019_new_table_catalog() IS DISTINCT FROM $expected_tables${"public.fsrs_manual_save_receipts":{"columns":[{"acl":null,"name":"user_id","type":"uuid","number":1,"default":null,"dropped":false,"notNull":true,"storage":"p","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":false,"compression":""},{"acl":null,"name":"operation_id","type":"text","number":2,"default":null,"dropped":false,"notNull":true,"storage":"x","identity":"","collation":"pg_catalog.default","generated":"","dimensions":0,"hasDefault":false,"compression":""},{"acl":null,"name":"requested_card_id","type":"uuid","number":3,"default":null,"dropped":false,"notNull":true,"storage":"p","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":false,"compression":""},{"acl":null,"name":"vocabulary_id","type":"uuid","number":4,"default":null,"dropped":false,"notNull":true,"storage":"p","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":false,"compression":""},{"acl":null,"name":"request","type":"jsonb","number":5,"default":null,"dropped":false,"notNull":true,"storage":"x","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":false,"compression":""},{"acl":null,"name":"created","type":"boolean","number":6,"default":null,"dropped":false,"notNull":true,"storage":"p","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":false,"compression":""},{"acl":null,"name":"received_at","type":"timestamp with time zone","number":7,"default":"clock_timestamp()","dropped":false,"notNull":true,"storage":"p","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":true,"compression":""}],"indexes":[{"kind":"i","live":true,"name":"fsrs_manual_save_receipts_pkey","ready":true,"valid":true,"unique":true,"options":null,"primary":true,"keyCount":2,"checkXmin":false,"clustered":false,"exclusion":false,"immediate":true,"definition":"CREATE UNIQUE INDEX fsrs_manual_save_receipts_pkey ON public.fsrs_manual_save_receipts USING btree (user_id, operation_id)","persistence":"p","accessMethod":"btree","attributeCount":2,"replicaIdentity":false},{"kind":"i","live":true,"name":"fsrs_manual_save_receipts_user_id_requested_card_id_key","ready":true,"valid":true,"unique":true,"options":null,"primary":false,"keyCount":2,"checkXmin":false,"clustered":false,"exclusion":false,"immediate":true,"definition":"CREATE UNIQUE INDEX fsrs_manual_save_receipts_user_id_requested_card_id_key ON public.fsrs_manual_save_receipts USING btree (user_id, requested_card_id)","persistence":"p","accessMethod":"btree","attributeCount":2,"replicaIdentity":false}],"policies":[{"name":"fsrs_manual_receipt_owner","roles":["authenticated"],"using":"(user_id = ( SELECT auth.uid() AS uid))","command":"r","withCheck":null,"permissive":true}],"relation":{"rls":true,"kind":"r","checks":2,"options":null,"forceRls":false,"hasRules":false,"partition":false,"hasSubclass":false,"persistence":"p","accessMethod":"heap","replicaIdentity":"d"},"constraints":[{"name":"fsrs_manual_save_receipts_operation_id_check","type":"c","local":true,"deferred":false,"noInherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((operation_id ~ '^[A-Za-z0-9_.:-]{1,200}$'::text))","inheritCount":0},{"name":"fsrs_manual_save_receipts_pkey","type":"p","local":true,"deferred":false,"noInherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (user_id, operation_id)","inheritCount":0},{"name":"fsrs_manual_save_receipts_request_check","type":"c","local":true,"deferred":false,"noInherit":false,"validated":true,"deferrable":false,"definition":"CHECK ((jsonb_typeof(request) = 'object'::text))","inheritCount":0},{"name":"fsrs_manual_save_receipts_user_id_fkey","type":"f","local":true,"deferred":false,"noInherit":true,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE","inheritCount":0},{"name":"fsrs_manual_save_receipts_user_id_requested_card_id_key","type":"u","local":true,"deferred":false,"noInherit":true,"validated":true,"deferrable":false,"definition":"UNIQUE (user_id, requested_card_id)","inheritCount":0}]},"fsrs_private.manual_save_settings":{"columns":[{"acl":null,"name":"singleton","type":"boolean","number":1,"default":"true","dropped":false,"notNull":true,"storage":"p","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":true,"compression":""},{"acl":null,"name":"enabled","type":"boolean","number":2,"default":"true","dropped":false,"notNull":true,"storage":"p","identity":"","collation":null,"generated":"","dimensions":0,"hasDefault":true,"compression":""},{"acl":null,"name":"contract_hash","type":"text","number":3,"default":null,"dropped":false,"notNull":false,"storage":"x","identity":"","collation":"pg_catalog.default","generated":"","dimensions":0,"hasDefault":false,"compression":""}],"indexes":[{"kind":"i","live":true,"name":"manual_save_settings_pkey","ready":true,"valid":true,"unique":true,"options":null,"primary":true,"keyCount":1,"checkXmin":false,"clustered":false,"exclusion":false,"immediate":true,"definition":"CREATE UNIQUE INDEX manual_save_settings_pkey ON fsrs_private.manual_save_settings USING btree (singleton)","persistence":"p","accessMethod":"btree","attributeCount":1,"replicaIdentity":false}],"policies":[],"relation":{"rls":false,"kind":"r","checks":1,"options":null,"forceRls":false,"hasRules":false,"partition":false,"hasSubclass":false,"persistence":"p","accessMethod":"heap","replicaIdentity":"d"},"constraints":[{"name":"manual_save_settings_pkey","type":"p","local":true,"deferred":false,"noInherit":true,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (singleton)","inheritCount":0},{"name":"manual_save_settings_singleton_check","type":"c","local":true,"deferred":false,"noInherit":false,"validated":true,"deferrable":false,"definition":"CHECK (singleton)","inheritCount":0}]}}$expected_tables$::jsonb
  THEN RAISE EXCEPTION 'fsrs019_new_table_definition_drift'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=ANY(ARRAY['fsrs_private.manual_save_settings'::regclass,'public.fsrs_manual_save_receipts'::regclass]) AND relowner<>owner_oid)
