 -- Fixed source/type/security checks precede every expected-fingerprint refresh.
 SELECT * INTO fn FROM pg_catalog.pg_proc WHERE oid='fsrs_private.iso_milliseconds(timestamptz)'::regprocedure;
 IF md5(fn.prosrc)<>'add674af992af196e741d68e525bcdbe' OR fn.proowner<>owner_oid OR fn.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname='sql')
