 IF md5(fn.prosrc)<>'771d6c4f3ecc170b6ae0eb685771ce4e' OR fn.proowner<>owner_oid OR fn.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql')
  OR fn.prosecdef IS DISTINCT FROM true OR fn.provolatile<>'s' OR fn.prokind<>'f' OR fn.proretset OR fn.proisstrict OR fn.proleakproof
  OR fn.prorettype<>'pg_catalog.jsonb'::regtype OR fn.pronargs<>2 OR fn.pronargdefaults<>0 OR fn.provariadic<>0
  OR fn.proargnames IS DISTINCT FROM ARRAY['p_actor','p_card_id']::text[] OR fn.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
  OR fn.proargtypes IS DISTINCT FROM array_to_string(ARRAY['pg_catalog.uuid'::regtype::oid,'pg_catalog.uuid'::regtype::oid],' ')::oidvector
  OR fn.proparallel<>'u' OR fn.prosupport<>0 OR fn.procost<>100 OR fn.prorows<>0
  OR has_function_privilege('service_role',fn.oid,'EXECUTE') IS DISTINCT FROM false
