  THEN RAISE EXCEPTION 'fsrs019_new_function_definition_drift: fsrs_private.vocabulary_registry_entry'; END IF;
SELECT * INTO fn FROM pg_catalog.pg_proc WHERE oid='public.fsrs_vocabulary_snapshot(uuid)'::regprocedure;
 IF md5(fn.prosrc)<>'3c21d30aea20a45f7210228a518e18e0' OR fn.proowner<>owner_oid OR fn.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql')
  OR fn.prosecdef IS DISTINCT FROM true OR fn.provolatile<>'s' OR fn.prokind<>'f' OR fn.proretset OR fn.proisstrict OR fn.proleakproof
  OR fn.prorettype<>'pg_catalog.jsonb'::regtype OR fn.pronargs<>1 OR fn.pronargdefaults<>0 OR fn.provariadic<>0
  OR fn.proargnames IS DISTINCT FROM ARRAY['p_actor']::text[] OR fn.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
  OR fn.proargtypes IS DISTINCT FROM array_to_string(ARRAY['pg_catalog.uuid'::regtype::oid],' ')::oidvector
  OR fn.proparallel<>'u' OR fn.prosupport<>0 OR fn.procost<>100 OR fn.prorows<>0
